{
  "name": "BioShake 加热振荡器",
  "name_en": "BioShake Heater-Shaker",
  "manufacturer": "",
  "description": "台式加热振荡器，用于对微孔板或样品板进行可控振荡并同时进行温度控制。设备带有可归位的移动平台和（可选）板锁定机构，能设定振荡速度、加速度/减速度，并报告当前温度以用于温控实验。常用于混匀、孵育和温度依赖的样品处理步骤。",
  "description_en": "A benchtop heater-shaker for microplates or sample plates that combines controllable orbital or linear shaking with temperature control. The device features a homing-capable moving platform, optional plate locking to secure plates, adjustable shake speed and accel/decel, and a temperature sensor for closed-loop heating. Used for mixing, incubation, and temperature-dependent sample processing.",
  "actions": [
    {
      "action_name": "auto-deactivate",
      "description": "停止温度控制并关闭加热输出",
      "description_en": "deactivate temperature control and stop heating output"
    },
    {
      "action_name": "auto-home",
      "description": "将平台归位到初始位置以准备运行",
      "description_en": "home the platform to its initial position to prepare for operation"
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定放置的板以固定样品位置",
      "description_en": "engage the plate locking mechanism to secure the sample plate"
    },
    {
      "action_name": "auto-reset",
      "description": "重置设备以清除错误状态并刷新通信缓冲",
      "description_en": "reset the device to clear error states and flush communication buffers"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度并启动温度控制回路",
      "description_en": "set the target temperature and start the temperature control loop"
    },
    {
      "action_name": "auto-setup",
      "description": "初始化设备（可选复位后归位）以准备运行",
      "description_en": "initialize the device (optionally reset then home) to prepare for runs"
    },
    {
      "action_name": "auto-shake",
      "description": "以指定转速和可选加速度启动振荡",
      "description_en": "start shaking at the specified speed with optional acceleration"
    },
    {
      "action_name": "auto-stop",
      "description": "停止所有运动与活动",
      "description_en": "stop all motion and activities"
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡，可选指定减速以平缓停机",
      "description_en": "stop shaking, optionally applying deceleration for a controlled stop"
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "释放板锁以便放置或取出样品板",
      "description_en": "release the plate locking mechanism to place or remove a sample plate"
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取设备是否支持板卡锁定机制",
      "description_en": "get whether the device supports a plate locking mechanism"
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取设备是否支持主动制冷功能",
      "description_en": "get whether the device supports active cooling"
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前测量的温度",
      "description_en": "get the current measured temperature"
    }
  ],
  "tag_hints": [
    "temperature control",
    "plate shaking",
    "microplate",
    "plate locking",
    "acceleration/deceleration control",
    "temperature sensing",
    "homing/reset"
  ]
}
